						<div class="tsvg-classic-block-desc">MIDWEST TROPICAL CUSTOM WATER FEATURES. (2014, JUNE 23). CUSTOM BUBBLE WALLS-LOBBY WATER WALL FEATURE-CHILDREN’S HOSPITAL GRAND RAPIDS, MICHIGAN ON VIDEOS. RETRIEVED FROM HTTPS://YOUTU.BE/Z5NM39DJAKS<p>See the largest Bubble Wall Water Feature at over 50′ wide by 20′ high! Watch how Midwest Tropical built one of the largest bubble wall installations — nearly 50′ wide by 20′ high! Midwest Tropical https://www.www.midwest-tropical.com/custo… designed and built this stunning Bubble Wall Water Feature as the focal point for the Helen DeVos Children’s Hospital in Grand Rapids, Michigan. Standing over 20′ high and stretching nearly 50′ wide this video showcases one of the largest bubble wall installations and the amazing effects it is capable of producing. If you are interested in any design build Bubble Walls, Bubble Panels, Water Walls or similar Custom Water Features please call Midwest Tropical at 888-365-2393, email info@www.midwest-tropical.com or visit https://www.www.midwest-tropical.com/custo… Utilizing computer controls and sophisticated LED lighting the bubbles and lights are choreographed to create a beautiful effect which can be customized to any size or application. Midwest Tropical is the inventor of the Bubble Wall, building large-scale bubble walls and water features for venues around the world. Water feature design, fabrication &amp; installation: Midwest Tropical Inc. www.www.midwest-tropical.com Videography: Daryl Vaughan – Creative Director, Light Partners www.darylvaughan.com</p></div>
