						<div class="tsvg-classic-block-desc">MIDWEST TROPICAL CUSTOM WATER FEATURES. (2014, AUGUST 4). OUTDOOR BUBBLE WALLS FOR BUS SHELTER DISPLAY IN CHICAGO ON VIDEOS. RETRIEVED FROM HTTPS://YOUTU.BE/2VJMQJ1O-94<p>This custom built outdoor bubble wall by Midwest Tropical https://www.www.midwest-tropical.com/custo… is installed outdoor in one of downtown Chicago’s busiest corners. As the inventor and holder of the patent on the Enclosed Water Wall Midwest Tropical Custom Water Features is the leading designer and manufacturer of bubble walls around the world! Midwest Tropical has completed one of the largest bubble wall installations in the world — nearly 50′ wide by 20′ high — with projects stretching from Michigan to Aruba to Cairo. Midwest Tropical can build you any size bubble wall custom made at their factory near Chicago, IL. To learn more about bubble walls, water walls, and water features visit https://www.www.midwest-tropical.com or call 888-365-2393 Water feature design, fabrication &amp; installation: Midwest Tropical Inc. www.www.midwest-tropical.com</p></div>
