						<div class="tsvg-classic-block-desc">MIDWEST TROPICAL CUSTOM WATER FEATURES. (2010, AUGUST 25). CUSTOM WATER PANEL BUBBLE WALL WITH LED LIGHTING-AMAZING, YOU HAVE TO WATCH! ON VIDEOS. RETRIEVED FROM HTTPS://YOUTU.BE/SV1DJWZRXCO<p>Bubble Walls, Bubble Panels and Water Wall Waterfalls are Midwest Tropical’s specialty with over 33 years experience see photos at https://www.midwest-tropical.com. Contact Midwest Tropical today to begin designing and building your custom indoor water feature wall. Call Midwest Tropical at 1-312-262-5390 or info@www.midwest-tropical.com Bubble Walls are Midwest Tropical’s specialty, see more bubble walls at https://www.midwest-tropical.com/bubbl… and https://www.midwest-tropical.com/rfq.htm Midwest Tropical builds every type of interior fountain wall and indoor water feature wall you can imagine. Specializing in fountain wall water features and commercial indoor water feature fountains Midwest Tropical begins the design process by presenting our clients with several interior water feature wall options including glass water walls, acrylic water walls, indoor fountain walls, water feature walls, steel water walls, stone water walls, tile water wall fountains, slate water walls features, granite fountain wall feature, lobby water features, interior fountains, indoor fountain features bubble wall feature options including acrylic bubble panels, bubble columns, bubble tubes, bubble tanks, chambered bubble panels, free floating bubble panels, circular rain curtain fountains, curved rain curtain water features, lobby rain curtain fountains, counter rain curtain water feature, free floating rain curtain fountain, rain curtain nozzle fountains, free falling rain water features and other materials designed to create a stunning interior rain curtain fountains. Creating large indoor water feature wall interior fountains for thousands of medical buildings, hotels, office lobbies, restaurants, casinos and other commercial interior areas Midwest Tropical can build any custom water feature wall or indoor fountain feature. As one of the only water feature manufacturers exclusively building all custom water feature fountains in the USA, Midwest Tropical can offer you the finest quality interior water feature and indoor fountain wall. Creating large indoor fountain water features for thousands of medical buildings, hotels, office lobbies, restaurants, casinos and other commercial interior areas Midwest Tropical will build a interior water feature fountain any size.</p></div>
