						<div class="tsvg-classic-block-desc">MIDWEST TROPICAL CUSTOM WATER FEATURES. (2014, APRIL 23). CUSTOM WATER FEATURE-INDOOR FOUNTAIN WITH REFLECTION POOL AT GREENBRIER RESORT CASINO ON VIDEOS. RETRIEVED FROM HTTPS://YOUTU.BE/9PPQUEDI8IA<p>This unique custom indoor fountain by Midwest Tropical https://www.midwest-tropical.com was specially design built for the Greenbrier Resort’s new casino serving as the focal point for the entry. Midwest Tropical designs and builds beautiful and versatile water features for both commercial and high end residential environment. If you are interested in any design build Fountains, Water Walls, Waterfalls, Bubble Walls, Bubble Panels, or similar Custom Water Features please call Midwest Tropical at 888-365-2393, email info@www.midwest-tropical.com or visit https://www.midwest-tropical.com/ Midwest Tropical is the inventor of the Bubble Wall, building large-scale bubble walls and water features for venues around the world. Water feature design, fabrication &amp; installation: Midwest Tropical Inc. www.www.midwest-tropical.com</p></div>
