			<li class="tsvg-li-content tsvg-classic-block-317386" data-tsvg-id="35" data-tsvg-effect="none" data-tsvg-src="https://www.youtube.com/embed/xXMDYvk3CUk" data-tsvg-link="" data-tsvg-target="_self">
				<figure class="tsvg-classic-block-inner-317386">
					<div class="tsvg-classic-block-items-317386" data-tsvg-effect="rgba(0,0,0,0.5)">
						<img decoding="async" loading="lazy" width="" height="" src="https://i.ytimg.com/vi/xXMDYvk3CUk/mqdefault.jpg" alt="img" class="tsvg-classic-block-img-317386" data-tsvg-img="rgba(0, 0, 0, 0)" title="Videos 33">
						<div class="tsvg-classic-block-desc">MIDWEST TROPICAL CUSTOM WATER FEATURES. (2014, AUGUST 19). WATER WALL INDOOR WATERFALL SCULPTURE-TWO TIERED 3D FOUNTAIN ON VIDEOS. RETRIEVED FROM HTTPS://YOUTU.BE/XXMDYVK3CUK<p>Midwest Tropical https://www.midwest-tropical.com/water… custom designs and build unique Water Walls and Custom Water Features. This waterfall being tested before shipping is a unique two tiered three dimensional fountain with two reflection pools overflowing on all side down the specially scored and textured sides creating a unique wave pattern as the cascades down to the basin. Midwest Tropical has been building custom water features including water walls, waterfalls, and bubble walls for over 30 years, see more at https://www.midwest-tropical.com/water…. To order a custom water wall or waterfall call 888-365-2393 or email info@www.midwest-tropical.com Water Walls are Midwest Tropical’s specialty, as well as indoor waterfalls and indoor waterfall walls, view these at https://www.midwest-tropical.com</p></div>
