						<div class="tsvg-classic-block-desc">MIDWEST TROPICAL CUSTOM WATER FEATURES. (2013, OCTOBER 8). GLASS WATER WALLS AND BUBBLER JETS IN WATER FEATURE FOUNTAIN ON VIDEOS. RETRIEVED FROM HTTPS://YOUTU.BE/HV19ZB5IW88<p>Midwest Tropical Custom Water Features https://www.midwest-tropical.com created this beautiful custom Fountain and Water Wall with Bubbler Jets for the entrance of a new building. Custom Water Walls &amp; Indoor Waterfalls are Midwest Tropical’s specialty, see more at https://www.midwest-tropical.com/custo… If you are interested in any Water Walls, Indoor Waterfalls or similar Custom Water Features please call Midwest Tropical at 888-365-2393, email info@www.midwest-tropical.com or visit https://www.midwest-tropical.com/water… Midwest Tropical is the inventor of the Bubble Wall, building large-scale bubble walls and water features for venues around the world.</p></div>
