						<div class="tsvg-classic-block-desc">MIDWEST TROPICAL CUSTOM WATER FEATURES. (2016, NOVEMBER 9). REFLECTION POOL WITH WEIR WATERFALLS AT EMBASSY SUITES SEATTLE BELLEVUE, WASHINGTON ON VIDEOS. RETRIEVED FROM HTTPS://YOUTU.BE/KUOA4PHZPG0<p>Midwest Tropical Custom Water Features shows how to design and build this amazing water wall waterfall with reflection pool and test the water walls flow and design for the Embassy Suites in Seattle Bellevue, Washington. Midwest Tropical has been building custom water features including water walls, waterfalls, and bubble walls for over 30 years, see more at https://www.midwest-tropical.com/water…. To order a custom water wall or waterfall call 888-365-2393 or email info@www.midwest-tropical.com Water Walls are Midwest Tropical’s specialty, as well as indoor waterfalls and indoor waterfall walls, view these at https://www.midwest-tropical.com Please visit https://www.midwesttropical.com/custom/ for more custom job examples.</p></div>
