			<li class="tsvg-li-content tsvg-classic-block-621188" data-tsvg-id="38" data-tsvg-effect="none" data-tsvg-src="https://www.youtube.com/embed/zPFi_J1gj9g" data-tsvg-link="" data-tsvg-target="_self">
				<figure class="tsvg-classic-block-inner-621188">
					<div class="tsvg-classic-block-items-621188" data-tsvg-effect="rgba(0,0,0,0.5)">
						<img decoding="async" loading="lazy" width="" height="" src="https://i.ytimg.com/vi/zPFi_J1gj9g/mqdefault.jpg" alt="img" class="tsvg-classic-block-img-621188" data-tsvg-img="rgba(0, 0, 0, 0)" title="Videos 37">
						<div class="tsvg-classic-block-desc">MIDWEST TROPICAL CUSTOM WATER FEATURES. (2014, APRIL 1). BUBBLE WALL WITH SHOW PERFOMANCE-AMAZING-CUSTOM WATER WALL FEATURE-YOU HAVE TO SEE! ON VIDEOS. RETRIEVED FROM HTTPS://YOUTU.BE/ZPFI_J1GJ9G<p>How to build and light this amazing four section custom Bubble Wall Waterfall by Midwest Tropical Custom Water Features https://www.midwest-tropical.com installed at the entrance of one of the premiere medical spas in Scottsdale, Arizona. Each bubble wall panel stands over 10′ high in this amazing display of water art which serves as the focal point of this professionally designed lobby. If you are interested in any design build Bubble Walls, Bubble Panels, Water Walls or similar Custom Water Features please call Midwest Tropical at 888-365-2393, email info@www.midwest-tropical.com or visit https://www.midwest-tropical.com/custo… Utilizing computer controls and sophisticated LED lighting the bubbles and lights are choreographed to create a beautiful effect which can be customized to any size or application. Midwest Tropical is the inventor of the Bubble Wall, building large-scale bubble walls and water features for venues around the world. Water feature design, fabrication &amp; installation: Midwest Tropical Inc. www.www.midwest-tropical.com</p></div>
