			<li class="tsvg-li-content tsvg-classic-block-621188" data-tsvg-id="39" data-tsvg-effect="none" data-tsvg-src="https://www.youtube.com/embed/p4atAWBg-Gc" data-tsvg-link="" data-tsvg-target="_self">
				<figure class="tsvg-classic-block-inner-621188">
					<div class="tsvg-classic-block-items-621188" data-tsvg-effect="rgba(0,0,0,0.5)">
						<img decoding="async" loading="lazy" width="" height="" src="https://i.ytimg.com/vi/p4atAWBg-Gc/mqdefault.jpg" alt="img" class="tsvg-classic-block-img-621188" data-tsvg-img="rgba(0, 0, 0, 0)" title="Videos 38">
						<div class="tsvg-classic-block-desc">MIDWEST TROPICAL CUSTOM WATER FEATURES. (2014, SEPTEMBER 25). BUBBLE TUBE COLUMN-CUSTOM DESIGN WATER FEATURE BUBBLING COLUMN ON VIDEOS. RETRIEVED FROM HTTPS://YOUTU.BE/P4ATAWBG-GC<p>Custom built Bubble Tube Column by Midwest Tropical Custom Water Features https://www.midwest-tropical.com is tested and functions including the stunning white lighting. As the inventor and holder of the patent on the Enclosed Water Wall Midwest Tropical Custom Water Features is the leading designer and manufacturer of bubble tubes and bubble walls around the world! Midwest Tropical has completed one of the largest bubble wall installations in the world — nearly 50′ wide by 20′ high — with projects stretching from Michigan to Aruba to Cairo. Midwest Tropical can build you any size bubble tube custom made at their factory near Chicago, IL. To learn more about bubble walls, water walls, and water features visit https://www.midwest-tropical.com or call 888-365-2393 Water feature design, fabrication &amp; installation: Midwest Tropical Inc. www.www.midwest-tropical.com</p></div>
