			<li class="tsvg-li-content tsvg-classic-block-621188" data-tsvg-id="40" data-tsvg-effect="none" data-tsvg-src="https://www.youtube.com/embed/FMjQYLGFT64" data-tsvg-link="" data-tsvg-target="_self">
				<figure class="tsvg-classic-block-inner-621188">
					<div class="tsvg-classic-block-items-621188" data-tsvg-effect="rgba(0,0,0,0.5)">
						<img decoding="async" loading="lazy" width="" height="" src="https://i.ytimg.com/vi/FMjQYLGFT64/mqdefault.jpg" alt="img" class="tsvg-classic-block-img-621188" data-tsvg-img="rgba(0, 0, 0, 0)" title="Videos 39">
						<div class="tsvg-classic-block-desc">MIDWEST TROPICAL CUSTOM WATER FEATURES. (2014, OCTOBER 3). CUSTOM WATER FEATURE COLUMN AT MCALLEN-MILLER INTERNATIONAL AIRPORT-BUBBLE WALLS ON VIDEOS. RETRIEVED FROM HTTPS://YOUTU.BE/FMJQYLGFT64<p>This Bubble Wall Water Feature installation is a spectacular Interior Water Wall Feature by Midwest Tropical https://www.midwest-tropical.com/ comprised of Bubble Walls up to 15′ high forming a 360 degree hexagonal bubble column at the new terminal of McAllen-Miller International Airport in McAllen, Texas, USA. The Bubble Walls create a beautiful and unique display which is the focal point of new airport terminal – a kinetic work of art – combines water, air and multi-coloured light in a synchronised, choreographed display of ethereal beauty! Water feature design, fabrication &amp; installation: Midwest Tropical-Custom Water Features https://www.midwest-tropical.com/ To get a quote for a Custom Bubble Wall, Indoor Water Wall or Custom Waterfalls email info@www.midwest-tropical.com or call 888-365-2393</p></div>
