						<div class="tsvg-classic-block-desc">MIDWEST TROPICAL CUSTOM WATER FEATURES. (2014, OCTOBER 14). CUSTOM BUBBLE TUBE-GIANT BUBBLE COLUMN WATER FEATURE ON VIDEOS. RETRIEVED FROM HTTPS://YOUTU.BE/L2DJIGNNAHA<p>Giant Bubble Tube designed and built by Midwest Tropical Custom Water Features https://www.midwest-tropical.com is tested and functions including color changing LED lighting. The bubble tube stands over 8′ high and is 24″ in diameter holding hundreds of gallons of water as bubbles gently rise creating a stunning visual experience. As the inventor and holder of the patent on the Enclosed Water Wall Midwest Tropical Custom Water Features is the leading designer and manufacturer of bubble tubes and bubble walls around the world! Midwest Tropical has completed one of the largest bubble wall installations in the world — nearly 50′ wide by 20′ high — with projects stretching from Michigan to Aruba to Cairo. Midwest Tropical can build you any size bubble tube custom made at their factory near Chicago, IL. To learn more about bubble walls, water walls, and water features visit https://www.midwest-tropical.com or call 888-365-2393 Water feature design, fabrication &amp; installation: Midwest Tropical Inc. www.www.midwest-tropical.com</p></div>
