						<div class="tsvg-classic-block-desc">MIDWEST TROPICAL CUSTOM WATER FEATURES. (2014, NOVEMBER 3). CUSTOM WATER FEATURE PROJECT: BUBBLE WALL WATERFALL AT MCALLEN-MILLER INTERNATIONAL AIRPORT ON VIDEOS. RETRIEVED FROM HTTPS://YOUTU.BE/OHLLLGUJOAI<p>See how Midwest Tropical’s latest Bubble Wall dances to music! This Bubble Wall Waterfall is a spectacular Water Feature by Midwest Tropical https://www.midwest-tropical.com/ comprised of 6 Bubble Walls each up to 15′ high forming a 360 degree hexagonal bubble column at the new terminal of McAllen-Miller International Airport in McAllen, Texas, USA. This beautiful and unique Water Feature combines water, air and multi-coloured light in a synchronised, choreographed display coordinated with the music sound track! Water feature design, fabrication &amp; installation: Midwest Tropical-Custom Water Features https://www.midwest-tropical.com/ To get a quote for a Custom Bubble Wall, Indoor Water Wall or Custom Waterfalls email info@www.midwest-tropical.com or call 888-365-2393</p></div>
