						<div class="tsvg-classic-block-desc">MIDWEST TROPICAL CUSTOM WATER FEATURES. (2016, NOVEMBER 3). BUBBLE WALL TUBE COLUMNS-ENCLOSED WATER FEATURES AT NICKLAUS CHILDREN’S HOSPITAL MIAMI, FLORIDA ON VIDEOS. RETRIEVED FROM HTTPS://YOUTU.BE/GC9XRYEMADC<p>Midwest Tropical shows how to design and build fully sealed enclosed water features including these stunning Bubble Wall Tube Columns for Nicklaus Children’s Hospital in Miami, Florida . These sealed enclosed Bubble Tubes require no regular maintenance or water filling and are a stunning water feature choice for a hospital or facility looking for a sealed water feature with no maintenance. Midwest Tropical has been building custom water features including bubble walls, water walls, bubble tube columns, waterfalls, and bubble walls for over 30 years, see more at https://www.midwest-tropical.com/water…. To order a custom water wall or waterfall call 888-365-2393 or email info@www.midwest-tropical.com Bubble Wall Tubes are Midwest Tropical’s specialty, as well as indoor waterfalls and indoor waterfall walls, view these at https://www.midwest-tropical.com</p></div>
